```tsx
import type { KeyboardEvent } from "react";
import "./ChecklistItem.css";

export interface ChecklistItemProps {
  title: string;
  detail?: string;
  minutes: number;
  done: boolean;
  onToggle: () => void;
}

export function ChecklistItem({
  title,
  detail,
  minutes,
  done,
  onToggle,
}: ChecklistItemProps): React.JSX.Element {
  const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>): void => {
    // Native <button> already handles Enter and Space; this only guards
    // against repeated activation from held keys.
    if (event.repeat) {
      event.preventDefault();
    }
  };

  return (
    <div className={done ? "checklist-item checklist-item--done" : "checklist-item"}>
      <button
        type="button"
        role="checkbox"
        aria-checked={done}
        aria-label={title}
        className="checklist-item__check"
        onClick={onToggle}
        onKeyDown={handleKeyDown}
      >
        <svg
          className="checklist-item__mark"
          viewBox="0 0 16 16"
          aria-hidden="true"
          focusable="false"
        >
          <path d="M3.5 8.5 6.5 11.5 12.5 4.5" />
        </svg>
      </button>

      <div className="checklist-item__text">
        <span className="checklist-item__title">{title}</span>
        {detail ? <span className="checklist-item__detail">{detail}</span> : null}
      </div>

      <span className="checklist-item__duration" aria-label={`${minutes} minutes`}>
        {minutes} min
      </span>
    </div>
  );
}
