.checklist-item {
  --ci-fg: var(--myelin-fg, #1d1f24);
  --ci-fg-muted: var(--myelin-fg-muted, #6b7079);
  --ci-fg-quiet: var(--myelin-fg-quiet, #9a9fa8);
  --ci-line: var(--myelin-line, #d9dce1);
  --ci-accent: var(--myelin-accent, #3f7a5a);
  --ci-accent-ink: var(--myelin-accent-ink, #ffffff);
  --ci-focus: var(--myelin-focus, #2f6fd1);
  --ci-surface-hover: var(--myelin-surface-hover, rgba(0, 0, 0, 0.035));

  display: flex;
  align-items: center;
  gap: 14px;
  min-height: 56px;
  padding: 10px 12px;
  border-radius: 12px;
  color: var(--ci-fg);
  font-family: inherit;
  transition: background-color 160ms ease;
}

.checklist-item:hover {
  background-color: var(--ci-surface-hover);
}

[data-theme="night"] .checklist-item {
  --ci-fg: var(--myelin-fg, #e7e9ee);
  --ci-fg-muted: var(--myelin-fg-muted, #a3a9b4);
  --ci-fg-quiet: var(--myelin-fg-quiet, #6d737e);
  --ci-line: var(--myelin-line, #2c3038);
  --ci-accent: var(--myelin-accent, #7fc39c);
  --ci-accent-ink: var(--myelin-accent-ink, #10231a);
  --ci-focus: var(--myelin-focus, #8ab4ff);
  --ci-surface-hover: var(--myelin-surface-hover, rgba(255, 255, 255, 0.04));
}

/* Round check button. Native <button> gives Enter/Space activation. */
.checklist-item__check {
  flex: 0 0 auto;
  display: inline-grid;
  place-items: center;
  width: 26px;
  height: 26px;
  margin: 0;
  padding: 0;
  border: 1.5px solid var(--ci-line);
  border-radius: 50%;
  background: transparent;
  color: var(--ci-accent-ink);
  cursor: pointer;
  transition:
    background-color 160ms ease,
    border-color 160ms ease,
    transform 120ms ease;
}

.checklist-item__check:hover {
  border-color: var(--ci-accent);
}

.checklist-item__check:active {
  transform: scale(0.94);
}

.checklist-item__check:focus-visible {
  outline: 2px solid var(--ci-focus);
  outline-offset: 3px;
}

.checklist-item__mark {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.25;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0;
  transform: scale(0.6);
  transition:
    opacity 160ms ease,
    transform 160ms ease;
}

.checklist-item--done .checklist-item__check {
  background-color: var(--ci-accent);
  border-color: var(--ci-accent);
}

.checklist-item--done .checklist-item__mark {
  opacity: 1;
  transform: scale(1);
}

/* Text block */
.checklist-item__text {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.checklist-item__title {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.35;
  color: var(--ci-fg);
  overflow-wrap: anywhere;
  transition: color 160ms ease;
}

.checklist-item__detail {
  font-size: 13px;
  line-height: 1.4;
  color: var(--ci-fg-muted);
  overflow-wrap: anywhere;
}

/* Done state: title recedes, detail follows. */
.checklist-item--done .checklist-item__title {
  color: var(--ci-fg-muted);
  text-decoration: line-through;
  text-decoration-color: var(--ci-fg-quiet);
  text-decoration-thickness: 1px;
}

.checklist-item--done .checklist-item__detail {
  color: var(--ci-fg-quiet);
}

/* Duration, right-aligned, stable digits. */
.checklist-item__duration {
  flex: 0 0 auto;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  color: var(--ci-fg-quiet);
  white-space: nowrap;
}

.checklist-item--done .checklist-item__duration {
  color: var(--ci-fg-quiet);
  opacity: 0.8;
}

@media (prefers-reduced-motion: reduce) {
  .checklist-item,
  .checklist-item__check,
  .checklist-item__mark,
  .checklist-item__title {
    transition: none;
  }
}
